const body = ($input.first().json.body ?? $input.first().json) || {};
const errors = [];
const required = ['branch_slug', 'sender_profile', 'audience_segment', 'channels', 'message_template'];
for (const field of required) {
  if (!body[field]) errors.push(`Missing required field: ${field}`);
}

const validChannels = ['email', 'whatsapp', 'sms'];
const channels = Array.isArray(body.channels) ? body.channels : [];
const badChannels = channels.filter((c) => !validChannels.includes(c));
if (channels.length === 0) errors.push('At least one channel must be selected');
if (badChannels.length > 0) errors.push(`Unknown channel(s): ${badChannels.join(', ')}`);

const validRoles = ['pro', 'branch_chairman', 'secretariat'];
if (body.sender_profile && !validRoles.includes(body.sender_profile)) {
  errors.push(`Unknown sender_profile: ${body.sender_profile}`);
}

const validSegments = ['all_members', 'executive_committee', 'financial_members'];
if (body.audience_segment && !validSegments.includes(body.audience_segment)) {
  errors.push(`Unknown audience_segment: ${body.audience_segment}`);
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    branch_slug: body.branch_slug,
    sender_profile: body.sender_profile,
    audience_segment: body.audience_segment,
    channels,
    message_template: body.message_template,
    is_urgent: !!body.is_urgent,
    requested_by: body.requested_by || 'unknown',
  },
}];

