// Normalizes field casing between the Postgres path (snake_case) and the
// Sheets path (sheet header casing) since both converge here.
function normalize(json) {
  return {
    member_id: json.member_id ?? json.id ?? json.ID,
    first_name: json.first_name ?? json.First_Name,
    last_name: json.last_name ?? json.Last_Name,
    email: json.email ?? json.Email ?? null,
    phone_number: json.phone_number ?? json.Phone_Number,
    financial_status: (json.financial_status ?? json.Financial_Status ?? 'unknown').toString().toLowerCase(),
    committee_role: (json.committee_role ?? json.Committee_Role ?? 'none').toString().toLowerCase(),
    amount_due: json.amount_due ?? json.Amount_Due ?? null,
    branch_id: json.branch_id,
  };
}

const segment = $('Validate & Normalize Input').first().json.audience_segment;
const normalized = $input.all().map((item) => normalize(item.json));

const filtered = normalized.filter((m) => {
  if (segment === 'all_members') return true;
  if (segment === 'executive_committee') return m.committee_role === 'executive';
  if (segment === 'financial_members') return m.financial_status === 'financial';
  return false;
});

return filtered.map((m) => ({ json: m }));

const member = $json;
const broadcast = $('Validate & Normalize Input').first().json;
const senderProfile = $('Fetch Sender Profile').first().json;

function substitute(template, values) {
  return template.replace(/\{(\w+)\}/g, (match, key) => (key in values ? String(values[key]) : match));
}

const values = {
  First_Name: member.first_name,
  Last_Name: member.last_name,
  Amount_Due: member.amount_due != null ? member.amount_due : '',
  Sender_Profile: senderProfile.display_name,
};

const bodyText = substitute(broadcast.message_template, values);
const personalized_message = bodyText + (senderProfile.signature_block || '');

return [{
  json: {
    ...member,
    broadcast_id: $('Create Broadcast Record').first().json.broadcast_id,
    sender_profile_id: senderProfile.sender_profile_id,
    sender_display_name: senderProfile.display_name,
    sms_sender_id: senderProfile.sms_sender_id,
    personalized_message,
    personalized_message_html: personalized_message.replace(/\n/g, '<br>'),
  },
}];

const isUrgent = $('Validate & Normalize Input').first().json.is_urgent;
return [{
  json: {
    ...$json,
    forcednd: isUrgent ? 1 : 0,
  },
}];

const resp = $json;
const ctx = $('Personalize Message').item.json;
const ok = !!(resp && resp.messageId);
return [{
  json: {
    member_id: ctx.member_id,
    broadcast_id: ctx.broadcast_id,
    branch_id: ctx.branch_id,
    channel: 'email',
    recipient_address: ctx.email,
    status: ok ? 'sent' : 'failed',
    provider_message_id: resp?.messageId ?? null,
    error_detail: ok ? null : JSON.stringify(resp),
  },
}];

