const resp = $json;
const ctx = $('Personalize Message').item.json;
const ok = !!(resp && resp.status === 1);
const phoneKey = ctx.phone_number.replace('+', '');
return [{
  json: {
    member_id: ctx.member_id,
    broadcast_id: ctx.broadcast_id,
    branch_id: ctx.branch_id,
    channel: 'sms',
    recipient_address: ctx.phone_number,
    status: ok ? 'sent' : 'failed',
    provider_message_id: resp?.messages?.[phoneKey] ?? resp?.msgid ?? null,
    error_detail: ok ? null : JSON.stringify(resp),
  },
}];
